#include "display.hpp"
#include "control.hpp"
#include "repl_memory.hpp"
#include <iostream>
#include <sstream>
#include <string>
#include "cpu.hpp"
#include "dump.hpp"
#include "memory.hpp"
namespace { bool num(const std::string& s,long& x){try{std::size_t p=0;x=std::stol(s,&p,0);return p==s.size();}catch(...){return false;}} bool addr(const std::string& s,std::size_t& x){long n=0;if(!num(s,n)||n<0)return false;x=static_cast<std::size_t>(n);return true;} void help(){std::cout << "show, cls, frame, plot <x> <y>, findnz <lo> <hi>, find <lo> <hi> <byte>, get16 <addr>, set16 <addr> <value>, run" << std::endl;std::cout<<"commands:\n  dump\n  get <addr>\n  set <addr> <value>\n  inc <addr>\n  reg <a|b> <0..255>\n  regs\n  step\n  help\n  quit\n";} }
int main(){Memory mem;CPU cpu;cpu.mem=&mem;std::cout<<"ember 0.5 - 4096 bytes and one tiny CPU. Type help.\n";std::string line;while(true){std::cout<<"ember> ";if(!std::getline(std::cin,line))break;std::istringstream w(line);std::string cmd,a,v;w>>cmd;if(cmd.empty())continue;if(cmd=="quit")break;else if(cmd=="help")help();else if(cmd=="dump")dump(mem);else if(cmd=="get"){std::size_t x=0;if(!(w>>a)||!addr(a,x))std::cout<<"usage: get <addr>\n";else if(x>=MEM_SIZE)std::cout<<"address is outside 0..4095\n";else show_byte(mem_get(mem,x));}else if(cmd=="set"){std::size_t x=0;long n=0;if(!(w>>a>>v)||!addr(a,x)||!num(v,n))std::cout<<"usage: set <addr> <value>\n";else if(x>=MEM_SIZE)std::cout<<"address is outside 0..4095\n";else if(n<0||n>255)std::cout<<"a byte is 0..255, got "<<n<<'\n';else mem_set(mem,x,static_cast<Byte>(n));}else if(cmd=="inc"){std::size_t x=0;if(!(w>>a)||!addr(a,x))std::cout<<"usage: inc <addr>\n";else if(x>=MEM_SIZE)std::cout<<"address is outside 0..4095\n";else mem_set(mem,x,static_cast<Byte>(mem_get(mem,x)+1U));}else if(cmd=="reg"){long n=0;if(!(w>>a>>v)||!num(v,n)||n<0||n>255)std::cout<<"usage: reg <a|b> <0..255>\n";else if(a=="a")cpu.a=static_cast<Byte>(n);else if(a=="b")cpu.b=static_cast<Byte>(n);else std::cout<<"unknown register: "<<a<<'\n';}else if(display_command(cmd,w,mem)){}else if(find_command(cmd,w,mem)){}else if(memory_command(cmd,w,mem)){}else if(cmd=="run"){run(cpu);}else if(cmd=="regs")dump_regs(cpu);else if(cmd=="step")step(cpu);else std::cout<<"unknown command: "<<cmd<<'\n';}}
